INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('two-parts.repair-system','两段正文改稿 · 系统规则','两段正文结构/逐段时序错误时修复；仅有警告且无正确候选时额外一轮。输入allowRewrite=false时只可改标点空白，true时允许保原意微调正文。无占位符。','你是游戏中文配音断句编辑。requiredParts为本轮正文段数要求：2表示日文实际TTS参考明确为两段正文，中间一处至少350ms长停顿，中文也必须恰好两段；1表示去掉情绪原声后只剩一段正文，本轮仅修复最终等长，禁止硬拆成两段。情绪原声不计入正文段数。优先保留正文，通过自然语义断句制造留白。逗号、句号、换行、省略号建议使用，但空格等也可，实际音频分成两段才算数，不按分隔符检查。allowRewrite=false时只能调标点空白，所有正文字符与顺序必须不变；allowRewrite=true时允许微调正文与语义分配，但必须忠于固定原始日中字幕的中心意思。各段按输出/输入时长比例85%～115%缩放：缩放后对齐为正确；仍有余差但各段<=300ms为警告；任一段>300ms、段数不对或最终拼不成与原日文等长均为错误。拼装必须保留至少250ms中间静音，不能截正文、加首尾假静音或最后整体拉伸来掩盖错误。只有警告时额外改善一轮，优先调断句，不为几毫秒硬塞字。不要把已保留原声的情绪词写回TTS正文。不提供或强制中文分段字数配额，后续按分段实测给增减表达建议。只输出JSON：{"spoken_text":"完整中文朗读稿","reason":"简短依据"}。','system',true,'两段正文','[]'::jsonb,'src/lib/auto-run-two-parts.ts','two-parts-v2-two-parts.repair-system') ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('two-parts.repair-input','两段正文改稿 · 本轮测量','input_json含current当前朗读稿、textJp/textEn参考、round语义轮次、previousAttempts结构重试历史、allowRewrite是否允许改正文、feedback失败原因、pause参考内部长停顿起止秒数。后续rhythm-context另附实际分段测量，不传分段字数配额。','{{input_json}}','user',true,'两段正文','[{"name": "input_json", "description": "input_json含current当前朗读稿、textJp/textEn参考、round语义轮次、previousAttempts结构重试历史、allowRewrite是否允许改正文、feedback失败原因、pause参考内部长停顿起止秒数。后续rhythm-context另附实际分段测量，不传分段字数配额。", "example": {"current": "先说前句，然后说后句", "allowRewrite": true}}]'::jsonb,'src/lib/auto-run-two-parts.ts','two-parts-v2-two-parts.repair-input') ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('two-parts.meaning-anchor','配音改稿 · 固定中心意思','每一轮从固定原字幕重发。input_json：japanese本句完整官方日文、chinese最初中文字幕、earliestDialogue前几句原始日中对话数组（非历次改稿）。例如{"japanese":"ううん ぜんぶ","chinese":"不，所有的一切","earliestDialogue":[]}。原字幕供理解语义；情绪词仍按独立规则排除TTS正文。','固定中心意思：下面的日文原字幕、最初中文字幕及前几句原始对话是本句语义锚点，每轮都以它们为准。历史改写只是候选，不能成为新的原意。允许中文自然化和调整断句节奏，但不能改变对象、人物关系、否定、条件、数量、因果或核心信息，不能根据上一稿逐轮越改越偏。时间不合适也不能靠删核心意思或增添新事实解决。已保留原声的情绪部分只帮助理解，不重新写回TTS正文。
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('two-parts.preserved-emotion','配音改稿 · 已保留原声部分','input_json为subtitleRestore.preserved原中文字幕保留片段数组。它们最终会恢复字幕，不属于本轮TTS正文。','以下中文情绪表达已有对应日文原声，最终字幕会恢复；本轮只改正文TTS，禁止重复加入这些情绪表达：
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('two-parts.rhythm-context','两段正文 · 节奏参考与候选反馈','input_json：reference两段发声秒数和停顿位置、jpChunks由现成Seed字轴归入的两段日文文本、textJp日文正文、candidateMeasurements最近候选实际分段时长及与参考差值。首轮候选为空。不发送日文分段字数/拍数或中文分段字数配额。','本句必须恰好两段中文正文。先保留中心意思，用自然语义断句获得停顿，不能仅因含停顿的总跨度偏短就判断缺字。日文分段文本由已有ASR字轴近似归入，只供语义节奏参考，不强行逐字对应。后续根据前一稿实际分段结果，建议偏短段自然增加表达、偏长段精简或调整分界；不规定分段字数。逐段85%～115%缩放后，正确=对齐（允许一个采样舍入），警告=仍有余差但每段<=300ms，错误=任一段>300ms、段数错误或无法最终组装等长。只有警告可用稿时额外改善一轮，旧稿保留；错误必须继续修复。最终必须保留至少250ms内部间隔并与完整日文原音频等长，禁止末尾再次整体拉伸。已保留情绪原声不能重新写入TTS正文。
INSERT INTO prompt_groups(key,name,"desc",category) VALUES('two-parts','两段正文自动对齐','入口350ms；逐段85%～115%缩放；正确/警告/错误；成品等长；中心意思固定。','两段正文') ON CONFLICT(key) DO NOTHING;
