INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) VALUES('rewrite.number-two','数量2的中文自然读法','原文或当前正文含2/２时附加；不检查时间/轮次/stem。无占位符。示例：2个人→两个人，第2次→第二次。','本句参考文字含数字2或２。改写中文朗读稿时，语义需要表达“两”（例如两个人、两次、两边）的地方必须写汉字“两”，不允许写数字2或２，避免TTS读法困惑。其他需要读作“二”的序号、编号等按语义保留正确表达，不要机械地把所有2替换成“两”。','user',true,'字幕改写','[]'::jsonb,'src/lib/rewrite-number-hint.ts','rewrite-number-two-v1') ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) SELECT key,name,"desc",prompt || E'\n' || '专项排除：独立招呼或征询的ねえ／ねぇ／ねー及拖长形式是正文，不可当拟声原声保留。ASR漏掉时是缺失正文，不能认成环境音；无法定位时走整体TTS降级。词内否定包含ねえ也不能凭子串认拟声。',role,true,category,placeholders,source_path,'two-parts-nee-v1-'||key FROM (SELECT DISTINCT ON(key) * FROM prompt_templates WHERE key='missing-fragment.system' AND enable=true ORDER BY key,updated_at DESC,id DESC) latest ON CONFLICT(seed_hash) DO NOTHING;
