-- 两段正文正式流程：独立key可在提示词库管理；幂等导入，不覆盖人工版本。
BEGIN;
{{input_json}}','user',true,'两段正文','[{"name": "input_json", "description": "每一轮从固定原字幕重发。input_json：japanese本句完整官方日文、chinese最初中文字幕、earliestDialogue前几句原始日中对话数组（非历次改稿）。例如{\"japanese\":\"ううん ぜんぶ\",\"chinese\":\"不，所有的一切\",\"earliestDialogue\":[]}。原字幕供理解语义；情绪词仍按独立规则排除TTS正文。", "example": {"japanese": "ううん ぜんぶ", "chinese": "不，所有的一切"}}]'::jsonb,'src/lib/auto-run-two-parts.ts','two-parts-v2-two-parts.meaning-anchor') ON CONFLICT(seed_hash) DO NOTHING;
{{input_json}}','user',true,'两段正文','[{"name": "input_json", "description": "input_json为subtitleRestore.preserved原中文字幕保留片段数组。它们最终会恢复字幕，不属于本轮TTS正文。", "example": {"japanese": "ううん ぜんぶ", "chinese": "不，所有的一切"}}]'::jsonb,'src/lib/auto-run-two-parts.ts','two-parts-v2-two-parts.preserved-emotion') ON CONFLICT(seed_hash) DO NOTHING;
{{input_json}}','user',true,'两段正文','[{"name": "input_json", "description": "input_json：reference两段发声秒数和停顿位置、jpChunks由现成Seed字轴归入的两段日文文本、textJp日文正文、candidateMeasurements最近候选实际分段时长及与参考差值。首轮候选为空。不发送日文分段字数/拍数或中文分段字数配额。", "example": {"japanese": "ううん ぜんぶ", "chinese": "不，所有的一切"}}]'::jsonb,'src/lib/auto-run-two-parts.ts','two-parts-v2-two-parts.rhythm-context') ON CONFLICT(seed_hash) DO NOTHING;
SELECT key,name,"desc",prompt || E'\n' || '独立情绪应答可保留日文原声并从中日正文中删除，例如ううん／うう对应中文“不”、ああ对应“嗯”，允许语义对应，不要求中日同音；最终字幕恢复原词且TTS不得重复。专项排除：ねえ／ねぇ／ねー及拖长写法是招呼征询正文，不归保留原声的拟声，参考音频和中文表达都留在正文TTS；ASR漏掉时按缺失正文处理，不能猜成环境音或拟声。',role,true,category,placeholders,source_path,'two-parts-emotion-v1'
FROM (SELECT DISTINCT ON(key) * FROM prompt_templates WHERE key='onomatopoeia-plan.system' AND enable=true ORDER BY key,updated_at DESC,id DESC) latest
ON CONFLICT(seed_hash) DO NOTHING;
COMMIT;
